<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,reactive,ref,watch} from 'vue';
import Icon from './Icon.vue';
import CustomerPicker from './CustomerPicker.vue';
import OpportunityLines from './OpportunityLines.vue';
type Request=<T>(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<T>;
type Scope={read:boolean;write:boolean};
type Access={contactRead:boolean;leads:Scope;opportunities:Scope;tasks:Scope;activityRead:boolean;activityWrite:boolean};
type Opportunity={id:string;customerId:string;customerName:string;sourceLeadId:string|null;sourceLeadName:string|null;title:string;ownerMemberId:string;ownerName:string;stage:string;amountCents:number;actualAmountCents:number|null;closeDate:string;nextAction:string;description:string;version:number;updatedAt:string;canWrite:boolean;canLink:boolean;linesLocked?:boolean;hasLines?:boolean};
type Task={id:string;customerId:string|null;customerName:string|null;opportunityId:string|null;opportunityTitle:string|null;title:string;description:string;assigneeMemberId:string;assigneeName:string;dueDate:string;priority:string;status:string;completedAt:string|null;version:number;overdue:boolean;canWrite:boolean};
type Activity={id:string;customerId:string;customerName:string;opportunityId:string|null;opportunityTitle:string|null;activityType:string;content:string;occurredAt:string;actorName:string};
type History={id:string;fromStage:string|null;toStage:string;reason:string;nextAction:string;amountCents:number;actualAmountCents:number|null;actorName:string;businessVersion:number;createdAt:string};
type Page<T>={items:T[];total:number};
type Board={stage:string;total:number;amountCents:number;actualAmountCents:number;items:Opportunity[]};
type SourceLead={id:string;customerId:string;title:string};
const props=withDefaults(defineProps<{section:string;request:Request;readonly:boolean;memberId:string;access:Access;customerRead:boolean;customerWrite:boolean;productRead:boolean;admin:boolean;delivery?:{reports:boolean;export:boolean;customerImport:boolean;attachmentRead:boolean};customerId?:string;sourceLead?:SourceLead|null}>(),{delivery:()=>({reports:false,export:false,customerImport:false,attachmentRead:false}),customerId:'',sourceLead:null});
const emit=defineEmits<{customer:[id:string];navigate:[section:string];clearFilter:[];followup:[id:string]}>();
const stageNames:Record<string,string>={CONTACT:'初次接触',NEEDS:'需求确认',SOLUTION:'方案讨论',NEGOTIATION:'报价谈判',READY:'签约准备',WON:'成交',LOST:'丢单'};
const stages=Object.keys(stageNames),openStages=stages.slice(0,5),priorityNames:Record<string,string>={LOW:'低',NORMAL:'普通',HIGH:'高'},activityNames:Record<string,string>={CALL:'电话沟通',VISIT:'客户拜访',MEETING:'会议',EMAIL:'邮件沟通',OTHER:'其他'};
const titles:Record<string,string>={dashboard:'CRM 工作台',opportunities:'商机与销售看板',tasks:'跟进待办',activities:'客户跟进记录'};
const summary=ref<Record<string,number|null>>({}),opportunities=ref<Opportunity[]>([]),tasks=ref<Task[]>([]),activities=ref<Activity[]>([]),board=ref<Board[]>([]);
type Forecast={month:string;stage:string;probability:number;total:number;amountCents:number;weightedCents:number};
const forecast=ref<Forecast[]>([]);
const busy=ref(false),error=ref(''),success=ref(''),q=ref(''),page=ref(1),total=ref(0),stageFilter=ref(''),taskStatus=ref('PENDING'),mine=ref(false),boardMode=ref(true);
const dialog=ref(''),editor=ref<Opportunity|Task|Activity|null>(null),modal=ref<HTMLElement|null>(null),key=ref(''),owners=ref<{id:string;name:string}[]>([]),historyRows=ref<History[]>([]),historyPage=ref(1),historyTotal=ref(0),linkedActivities=ref<Activity[]>([]),linkedTasks=ref<Task[]>([]),detailTab=ref('history');
const source=ref<SourceLead|null>(null),opChoices=ref<Opportunity[]>([]),opPage=ref(1),opTotal=ref(0),opQuery=ref(''),opLoading=ref(false);
const form=reactive({customerId:'',customerName:'',opportunityId:'',opportunityTitle:'',title:'',description:'',ownerMemberId:'',amount:'0.00',closeDate:'',nextAction:'',stage:'',reason:'',actualAmount:'',assigneeMemberId:'',dueDate:'',priority:'NORMAL',activityType:'CALL',content:'',occurredAt:''});
const opp=computed(()=>editor.value&&'stage' in editor.value?editor.value as Opportunity:null),task=computed(()=>editor.value&&'dueDate' in editor.value?editor.value as Task:null);
const canCreate=computed(()=>!props.readonly&&(props.section==='opportunities'?props.access.opportunities.write&&props.customerWrite:props.section==='tasks'?props.access.tasks.write:props.access.activityWrite));
const canSave=computed(()=>!props.readonly&&(dialog.value==='stage'?!!opp.value?.canWrite:dialog.value==='opportunity'?props.access.opportunities.write&&props.customerWrite&&(!editor.value||!!opp.value?.canWrite):dialog.value==='task'?props.access.tasks.write&&(!editor.value||!!task.value?.canWrite&&task.value.status==='PENDING'):dialog.value==='activity'?props.access.activityWrite&&!editor.value:false));
const nextStages=computed(()=>opp.value?stages.filter(s=>s==='LOST'||s==='WON'&&opp.value?.stage==='READY'||openStages.includes(s)&&Math.abs(stages.indexOf(s)-stages.indexOf(opp.value!.stage))===1):[]);
const modules=computed(()=>[
 {id:'customers',name:'客户中心',description:'维护客户资料与协作范围',show:props.customerRead},
 {id:'contacts',name:'联系人',description:'管理客户联系渠道',show:props.access.contactRead},
 {id:'leads',name:'线索中心',description:'联系、确认并转为客户',show:props.access.leads.read},
 {id:'opportunities',name:'商机与看板',description:'阶段推进与成交记录',show:props.access.opportunities.read&&props.customerRead},
 {id:'activities',name:'客户跟进',description:'记录每次沟通内容和结果',show:props.access.activityRead},
 {id:'tasks',name:'跟进待办',description:'安排下一步、检查逾期和完成',show:props.access.tasks.read},
 {id:'reports',name:'数据报表',description:'查看真实范围内经营统计',show:props.delivery.reports},
 {id:'exchange',name:'导入导出',description:'预校验入库与受控下载',show:props.delivery.export||props.delivery.customerImport},
 {id:'attachments',name:'客户附件',description:'按客户与商机权限保存文件',show:props.delivery.attachmentRead},
 {id:'members',name:'企业管理',description:'成员、部门、权限与订阅',show:props.admin}
].filter(m=>m.show));
function money(cents:number|null|undefined){return cents==null?'—':'¥'+(Number(cents)/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});}
function cents(value:string){if(!/^\d{1,10}(\.\d{1,2})?$/.test(value.trim()))throw new Error('金额需为非负数，最多两位小数');const [whole,decimal='']=value.trim().split('.');const v=Number(whole)*100+Number(decimal.padEnd(2,'0'));if(v>100000000000)throw new Error('金额超出支持范围');return v;}
function date(value:string){return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'short',timeStyle:'short'}).format(new Date(value));}
function today(){return new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());}
function localNow(){const parts=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date());return parts.replace(' ','T');}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){const failure=e as Error&{status?:number;code?:string};error.value=failure.message||'操作未完成';if([401,403,404].includes(failure.status??0)||failure.code==='TENANT_CONTEXT_CHANGED'){opportunities.value=[];tasks.value=[];activities.value=[];board.value=[];summary.value={};total.value=0;dialog.value='';editor.value=null;linkedActivities.value=[];linkedTasks.value=[];historyRows.value=[];}}finally{busy.value=false;}}
async function load(){
 const filter=props.customerId?'&customerId='+props.customerId:'';const search='&q='+encodeURIComponent(q.value);
 if(props.section==='dashboard'){summary.value=await props.request('/sales/summary');if(props.access.tasks.read)tasks.value=(await props.request<Page<Task>>('/tasks?mine=true&status=PENDING&pageSize=5')).items;return;}
 if(props.section==='opportunities'){
  const first=today().slice(0,7)+'-01',last=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date(new Date(first+'T12:00:00+08:00').setMonth(Number(first.slice(5,7))+4))).slice(0,7)+'-01';
  forecast.value=await props.request(`/opportunities/forecast?from=${first}&to=${last}`);
  if(boardMode.value)board.value=await props.request('/opportunities/board?'+search.slice(1)+filter);
  else {const r=await props.request<Page<Opportunity>>(`/opportunities?page=${page.value}&pageSize=20&stage=${stageFilter.value}${search}${filter}`);opportunities.value=r.items;total.value=r.total;}
 }else if(props.section==='tasks'){const r=await props.request<Page<Task>>(`/tasks?page=${page.value}&pageSize=20&status=${taskStatus.value}&mine=${mine.value}${search}${filter}`);tasks.value=r.items;total.value=r.total;}
 else{const r=await props.request<Page<Activity>>(`/activities?page=${page.value}&pageSize=20${search}${filter}`);activities.value=r.items;total.value=r.total;}
}
function find(){page.value=1;return run(load);}
function turn(delta:number){page.value+=delta;return run(load);}
function chooseStage(stage:string){stageFilter.value=stage;boardMode.value=false;return find();}
function mode(value:boolean){boardMode.value=value;return find();}
function close(){if(!busy.value){dialog.value='';editor.value=null;source.value=null;}}
let previousFocus:HTMLElement|null=null,previousOverflow:string|null=null;
function restoreScroll(){if(previousOverflow!==null){document.body.style.overflow=previousOverflow;previousOverflow=null;}}
watch(dialog,async(value,old)=>{if(value&&!old){previousFocus=document.activeElement as HTMLElement;previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';}if(value){await nextTick();modal.value?.querySelector<HTMLElement>('button:not(:disabled),input:not(:disabled)')?.focus({preventScroll:true});}else{restoreScroll();previousFocus?.focus({preventScroll:true});}});
function keys(e:KeyboardEvent){if(!dialog.value)return;if(e.key==='Escape')close();if(e.key==='Tab'){const nodes=modal.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)');if(!nodes?.length)return;const first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}
onMounted(()=>document.addEventListener('keydown',keys));onUnmounted(()=>{document.removeEventListener('keydown',keys);restoreScroll();});
function reset(){editor.value=null;source.value=null;key.value=crypto.randomUUID();success.value='';historyRows.value=[];linkedActivities.value=[];linkedTasks.value=[];historyPage.value=1;historyTotal.value=0;detailTab.value='history';opChoices.value=[];opPage.value=1;opQuery.value='';opTotal.value=0;Object.assign(form,{customerId:props.customerId,customerName:'',opportunityId:'',opportunityTitle:'',title:'',description:'',ownerMemberId:'',amount:'0.00',closeDate:today(),nextAction:'',stage:'',reason:'',actualAmount:'',assigneeMemberId:'',dueDate:today(),priority:'NORMAL',activityType:'CALL',content:'',occurredAt:localNow()});}
async function history(){if(opp.value){const r=await props.request<Page<History>>(`/opportunities/${opp.value.id}/history?page=${historyPage.value}&pageSize=20`);historyRows.value=r.items;historyTotal.value=r.total;}}
function historyTurn(delta:number){historyPage.value+=delta;return run(history);}
async function detail(target:string){detailTab.value=target;if(!opp.value)return;if(target==='history')await history();if(target==='activities'){const r=await props.request<Page<Activity>>(`/activities?opportunityId=${opp.value.id}&pageSize=20`);linkedActivities.value=r.items;}if(target==='tasks'){const r=await props.request<Page<Task>>(`/tasks?opportunityId=${opp.value.id}&status=&pageSize=20`);linkedTasks.value=r.items;}}
function openOpportunity(item?:Opportunity,lead?:SourceLead){return run(async()=>{reset();if(item){const o=await props.request<Opportunity>('/opportunities/'+item.id);editor.value=o;Object.assign(form,o,{amount:(o.amountCents/100).toFixed(2)});await history();}else if(lead){source.value=lead;form.customerId=lead.customerId;form.title=lead.title;}
 if(!props.readonly&&props.access.opportunities.write&&props.customerWrite)owners.value=await props.request('/opportunities/owners');
 if(!item)form.ownerMemberId=owners.value.find(m=>m.id===props.memberId)?.id??owners.value[0]?.id??'';if(form.customerId&&!form.customerName)form.customerName=(await props.request<{name:string}>('/customers/'+form.customerId)).name;dialog.value='opportunity';});}
function openStage(item:Opportunity,to?:string){return run(async()=>{const current=await props.request<Opportunity>('/opportunities/'+item.id);if(!current.canWrite)throw new Error('该商机当前不可推进');editor.value=current;key.value=crypto.randomUUID();Object.assign(form,{stage:to??'',reason:'',nextAction:current.nextAction,actualAmount:''});dialog.value='stage';});}
function openTask(item?:Task,linked?:Opportunity){return run(async()=>{reset();if(item){editor.value=await props.request<Task>('/tasks/'+item.id);Object.assign(form,editor.value);}else if(linked){Object.assign(form,{customerId:linked.customerId,customerName:linked.customerName,opportunityId:linked.id,opportunityTitle:linked.title});}
 if(!props.readonly&&props.access.tasks.write)owners.value=await props.request('/tasks/owners');if(!item)form.assigneeMemberId=owners.value.find(m=>m.id===props.memberId)?.id??owners.value[0]?.id??'';if(form.customerId&&!form.customerName)form.customerName=(await props.request<{name:string}>('/customers/'+form.customerId)).name;dialog.value='task';});}
function openActivity(item?:Activity,linked?:Opportunity){return run(async()=>{reset();if(item){editor.value=await props.request<Activity>('/activities/'+item.id);Object.assign(form,editor.value);form.occurredAt='';}else if(linked){Object.assign(form,{customerId:linked.customerId,customerName:linked.customerName,opportunityId:linked.id,opportunityTitle:linked.title});}if(form.customerId&&!form.customerName)form.customerName=(await props.request<{name:string}>('/customers/'+form.customerId)).name;dialog.value='activity';});}
function create(){return props.section==='opportunities'?openOpportunity():props.section==='tasks'?openTask():openActivity();}
let opGeneration=0;
async function loadChoices(){if(!form.customerId||!props.access.opportunities.read||!canSave.value)return;const generation=++opGeneration;opLoading.value=true;try{const r=await props.request<Page<Opportunity>>(`/opportunities?customerId=${form.customerId}&q=${encodeURIComponent(opQuery.value)}&page=${opPage.value}&pageSize=20`);if(generation===opGeneration){opChoices.value=r.items.filter(o=>o.canLink);opTotal.value=r.total;}}catch(e){if(generation===opGeneration)error.value=e instanceof Error?e.message:'商机未加载';}finally{if(generation===opGeneration)opLoading.value=false;}}
function chooseCustomer(id:string){form.customerId=id;form.customerName='';form.opportunityId='';form.opportunityTitle='';opChoices.value=[];opQuery.value='';opPage.value=1;opGeneration++;loadChoices();}
function choicePage(delta:number){opPage.value+=delta;loadChoices();}
async function save(){return run(async()=>{
 if(dialog.value==='stage'&&opp.value){await props.request(`/opportunities/${opp.value.id}/stage`,'POST',{expectedVersion:opp.value.version,stage:form.stage,reason:form.reason,nextAction:['WON','LOST'].includes(form.stage)?'':form.nextAction,...(form.stage==='WON'?{actualAmountCents:cents(form.actualAmount)}:{})},{'Idempotency-Key':key.value});}
 else if(dialog.value==='opportunity'){const input={title:form.title,ownerMemberId:form.ownerMemberId,amountCents:cents(form.amount),closeDate:form.closeDate,nextAction:form.nextAction,description:form.description};if(opp.value)await props.request('/opportunities/'+opp.value.id,'PATCH',{...input,expectedVersion:opp.value.version});else await props.request('/opportunities','POST',{...input,customerId:form.customerId,...(source.value?{sourceLeadId:source.value.id}:{})},{'Idempotency-Key':key.value});}
 else if(dialog.value==='task'){const input={title:form.title,description:form.description,assigneeMemberId:form.assigneeMemberId,dueDate:form.dueDate,priority:form.priority};if(task.value)await props.request('/tasks/'+task.value.id,'PATCH',{...input,expectedVersion:task.value.version});else await props.request('/tasks','POST',{...input,customerId:form.customerId||null,opportunityId:form.opportunityId||null},{'Idempotency-Key':key.value});}
 else if(dialog.value==='activity')await props.request('/activities','POST',{customerId:form.customerId,opportunityId:form.opportunityId||null,activityType:form.activityType,content:form.content,occurredAt:new Date(form.occurredAt+':00+08:00').toISOString()},{'Idempotency-Key':key.value});
 dialog.value='';editor.value=null;source.value=null;page.value=1;await load();success.value='已保存到企业数据库';
 });}
function taskState(item:Task){return run(async()=>{await props.request(`/tasks/${item.id}/${item.status==='DONE'?'reopen':'complete'}`,'POST',{expectedVersion:item.version},{'Idempotency-Key':crypto.randomUUID()});await load();success.value=item.status==='DONE'?'待办已重新开启':'待办已完成';});}
function showCustomer(){const id=opp.value?.customerId;if(id){close();emit('customer',id);}}
function linesUpdated(value:{version:number;amountCents:number}){if(opp.value){editor.value={...opp.value,version:value.version,amountCents:value.amountCents};form.amount=(value.amountCents/100).toFixed(2);}}
function linkFromDetail(target:string){const item=opp.value;if(!item)return;if(target==='activity')openActivity(undefined,item);else openTask(undefined,item);}
const dragged=ref<Opportunity|null>(null);
function drop(stage:string){const item=dragged.value;dragged.value=null;if(item&&item.stage!==stage)openStage(item,stage);}
watch(()=>[props.section,props.customerId,props.sourceLead?.id],async()=>{page.value=1;q.value='';stageFilter.value='';taskStatus.value='PENDING';mine.value=false;dialog.value='';editor.value=null;await run(load);if(props.sourceLead&&props.section==='opportunities'&&canCreate.value)await openOpportunity(undefined,props.sourceLead);},{immediate:true});
</script>
<template>
 <section class="sales-workspace">
  <div class="page-heading"><div><span class="eyebrow">{{section==='dashboard'?'YOUR ENTERPRISE CRM':'SALES WORKSPACE'}}</span><h1>{{titles[section]}}</h1><p>{{section==='dashboard'?'客户企业工作区 · 当前数据保存在云端，可重新登录继续使用。':section==='opportunities'?'把需求推进到成交，保留每次阶段变化的依据。':section==='tasks'?'为下一次跟进明确执行人、截止日期与完成状态。':'记录已发生的沟通，形成可追踪的客户时间线。'}}</p></div><button v-if="section!=='dashboard'&&canCreate" class="btn primary" :disabled="busy" @click="create"><Icon name="plus" :size="17"/>{{section==='opportunities'?'新增商机':section==='tasks'?'新增待办':'记录跟进'}}</button></div>
  <div v-if="readonly" class="sales-alert warning">企业订阅当前为只读状态，可以查看已有资料。</div><div v-if="error&&!dialog" class="sales-alert error" role="alert">{{error}}</div><div v-if="success" class="sales-alert ok" role="status">{{success}}</div>
  <template v-if="section==='dashboard'">
   <div class="sales-summary"><button v-if="summary.customers!=null" class="card" @click="emit('navigate','customers')"><span>可见客户</span><strong>{{summary.customers}}</strong></button><button v-if="summary.leads!=null" class="card" @click="emit('navigate','leads')"><span>可见线索</span><strong>{{summary.leads}}</strong></button><button v-if="summary.openOpportunities!=null" class="card" @click="emit('navigate','opportunities')"><span>进行中的商机</span><strong>{{summary.openOpportunities}}</strong></button><button v-if="summary.myPendingTasks!=null" class="card" @click="emit('navigate','tasks')"><span>我的待办 / 逾期</span><strong>{{summary.myPendingTasks}} <small>/ {{summary.myOverdueTasks}}</small></strong></button></div>
   <section class="card sales-module-card"><h2>开始今天的客户经营</h2><div class="sales-module-grid"><button v-for="m in modules" :key="m.id" @click="emit('navigate',m.id)"><strong>{{m.name}}<Icon name="arrow" :size="16"/></strong><span>{{m.description}}</span></button></div></section>
   <section v-if="access.tasks.read" class="card sales-module-card"><div class="sales-row"><h2>我的近期待办</h2><button class="text-button" @click="emit('navigate','tasks')">查看全部</button></div><div v-for="t in tasks" :key="t.id" class="sales-upcoming"><button class="text-button" @click="openTask(t)">{{t.title}}</button><span :class="{'sales-danger':t.overdue}">{{t.dueDate}}{{t.overdue?' · 已逾期':''}}</span><button v-if="t.canWrite&&!readonly" class="text-button" :disabled="busy" @click="taskState(t)">完成</button></div><p v-if="!tasks.length" class="sales-muted">暂无待办，可以从客户或商机安排下一步。</p></section>
   <p class="sales-muted">当前已开放完整基础 CRM 流程、真实报表、导入导出、附件与站内提醒；企业管理和平台运营使用各自授权入口。</p>
  </template>
  <template v-else>
   <div v-if="customerId" class="sales-filter"><span>当前仅显示此客户的{{section==='opportunities'?'商机':section==='tasks'?'待办':'跟进'}}</span><button class="text-button" :disabled="busy" @click="emit('clearFilter')">查看全部</button></div>
   <div class="sales-toolbar"><form @submit.prevent="find"><Icon name="search" :size="18"/><input v-model="q" :placeholder="section==='opportunities'?'商机名称或客户':section==='tasks'?'待办内容':'客户或跟进内容'" aria-label="搜索当前可见资料" maxlength="100"/><button class="btn secondary" :disabled="busy">搜索</button></form><div v-if="section==='opportunities'" class="sales-modes"><button :class="{active:boardMode}" :disabled="busy" @click="mode(true)">销售看板</button><button :class="{active:!boardMode}" :disabled="busy" @click="mode(false)">列表</button></div><template v-if="section==='tasks'"><select v-model="taskStatus" aria-label="待办状态" :disabled="busy" @change="find"><option value="PENDING">未完成</option><option value="OVERDUE">已逾期</option><option value="DONE">已完成</option><option value="">全部状态</option></select><label class="sales-check"><input v-model="mine" type="checkbox" :disabled="busy" @change="find"/>只看我的</label></template><button class="icon-button" aria-label="刷新业务资料" :disabled="busy" @click="run(load)"><Icon name="refresh"/></button></div>
   <section v-if="section==='opportunities'" class="card sales-forecast"><div class="sales-row"><div><h2>未来六个月销售预测</h2><p class="sales-muted">按当前企业行业配置中的阶段概率计算；仅统计你有权查看且未关闭的商机，按预计成交月份分组。</p></div><strong>加权预计 {{money(forecast.reduce((sum,r)=>sum+Number(r.weightedCents),0))}}</strong></div><div v-if="forecast.length" class="sales-forecast-grid"><div v-for="r in forecast" :key="r.month+r.stage"><small>{{r.month}} · {{stageNames[r.stage]}} · {{r.probability}}%</small><strong>{{money(Number(r.weightedCents))}}</strong><span>{{r.total}} 项 · 原始 {{money(Number(r.amountCents))}}</span></div></div><p v-else class="sales-muted">未来六个月暂无预计成交的在途商机。</p></section>
   <div v-if="section==='opportunities'&&boardMode" class="sales-board" aria-label="按销售阶段排列的商机"><article v-for="stage in board" :key="stage.stage" class="sales-column" @dragover.prevent @drop.prevent="drop(stage.stage)"><header><h2>{{stageNames[stage.stage]}} <small>{{stage.total}}</small></h2><strong>{{money(stage.stage==='WON'?stage.actualAmountCents:stage.amountCents)}}</strong></header><button v-for="o in stage.items" :key="o.id" class="sales-op-card" :draggable="o.canWrite&&!readonly" @dragstart="dragged=o" @dragend="dragged=null" @click="openOpportunity(o)"><strong>{{o.title}}</strong><span>{{o.customerName}}</span><b>{{money(o.stage==='WON'?o.actualAmountCents:o.amountCents)}}</b><small>{{o.ownerName}} · {{o.closeDate}}</small><small v-if="o.nextAction">下一步：{{o.nextAction}}</small></button><p v-if="!stage.items.length" class="sales-muted">暂无可见商机</p><button v-if="stage.total" class="text-button" @click="chooseStage(stage.stage)">查看该阶段全部 {{stage.total}} 项</button></article></div>
   <p v-if="section==='opportunities'&&boardMode" class="sales-muted">每列显示最近 12 项，数量和金额统计全部可见记录。拖动会打开阶段确认窗口；也可在资料中点击“推进阶段”。</p>
   <section v-else class="card sales-data"><div v-if="section==='opportunities'" class="sales-stage-tabs"><button :class="{active:!stageFilter}" @click="chooseStage('')">全部</button><button v-for="s in stages" :key="s" :class="{active:stageFilter===s}" @click="chooseStage(s)">{{stageNames[s]}}</button></div><div class="table-scroll">
    <table v-if="section==='opportunities'"><thead><tr><th>商机 / 客户</th><th>阶段</th><th>预计 / 成交金额</th><th>负责人</th><th>预计成交日期</th><th>操作</th></tr></thead><tbody><tr v-for="o in opportunities" :key="o.id"><td><strong>{{o.title}}</strong><small>{{o.customerName}}</small></td><td>{{stageNames[o.stage]}}</td><td>{{money(o.amountCents)}}<small>成交：{{money(o.actualAmountCents)}}</small></td><td>{{o.ownerName}}</td><td>{{o.closeDate}}</td><td><div class="sales-actions"><button class="text-button" :disabled="busy" @click="emit('followup',o.id)">跟进档案</button><button class="text-button" :disabled="busy" @click="openOpportunity(o)">查看{{o.canWrite?' / 编辑':''}}</button><button v-if="o.canWrite&&!readonly" class="text-button" :disabled="busy" @click="openStage(o)">推进阶段</button></div></td></tr><tr v-if="!opportunities.length"><td colspan="6" class="empty-cell">{{busy?'正在加载…':'暂无可见商机'}}</td></tr></tbody></table>
    <table v-else-if="section==='tasks'"><thead><tr><th>待办 / 关联资料</th><th>执行人</th><th>截止日期</th><th>优先级</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="t in tasks" :key="t.id"><td><strong>{{t.title}}</strong><small>{{t.customerName||'独立待办'}}{{t.opportunityTitle?' · '+t.opportunityTitle:''}}</small></td><td>{{t.assigneeName}}</td><td :class="{'sales-danger':t.overdue}">{{t.dueDate}}{{t.overdue?' · 逾期':''}}</td><td>{{priorityNames[t.priority]}}</td><td>{{t.status==='DONE'?'已完成':'未完成'}}</td><td><div class="sales-actions"><button class="text-button" :disabled="busy" @click="openTask(t)">查看{{t.canWrite&&t.status==='PENDING'?' / 编辑':''}}</button><button v-if="t.canWrite&&!readonly" class="text-button" :disabled="busy" @click="taskState(t)">{{t.status==='DONE'?'重新开启':'完成'}}</button></div></td></tr><tr v-if="!tasks.length"><td colspan="6" class="empty-cell">{{busy?'正在加载…':'当前筛选下没有可见待办'}}</td></tr></tbody></table>
    <table v-else><thead><tr><th>客户 / 商机</th><th>沟通方式</th><th>沟通内容</th><th>记录人</th><th>发生时间（上海）</th><th>操作</th></tr></thead><tbody><tr v-for="a in activities" :key="a.id"><td>{{a.customerName}}<small>{{a.opportunityTitle||'客户跟进'}}</small></td><td>{{activityNames[a.activityType]}}</td><td class="sales-content-preview">{{a.content}}</td><td>{{a.actorName}}</td><td>{{date(a.occurredAt)}}</td><td><button class="text-button" :disabled="busy" @click="openActivity(a)">查看记录</button></td></tr><tr v-if="!activities.length"><td colspan="6" class="empty-cell">{{busy?'正在加载…':'暂无可见跟进记录'}}</td></tr></tbody></table>
   </div><footer class="sales-pagination"><span>共 {{total}} 项 · 第 {{page}} 页</span><button class="btn secondary" :disabled="busy||page<=1" @click="turn(-1)">上一页</button><button class="btn secondary" :disabled="busy||page*20>=total" @click="turn(1)">下一页</button></footer></section>
  </template>
  <Teleport to="body"><div v-if="dialog" class="modal-backdrop" @click.self="close"><section ref="modal" class="sales-dialog" role="dialog" aria-modal="true" aria-labelledby="sales-dialog-title"><header class="sales-dialog-header"><h2 id="sales-dialog-title">{{dialog==='stage'?'推进商机阶段':dialog==='opportunity'?(editor?'商机资料':'新增商机'):dialog==='task'?(editor?'待办资料':'新增跟进待办'):(editor?'客户跟进记录':'记录客户跟进')}}</h2><button class="icon-button" :disabled="busy" aria-label="关闭业务窗口" @click="close"><Icon name="close"/></button></header><form @submit.prevent="save"><div class="sales-dialog-body"><fieldset :disabled="busy||!canSave">
   <template v-if="dialog==='stage'"><p class="sales-callout">{{opp?.title}} · 当前：{{stageNames[opp?.stage??'']}}</p><div class="sales-form-grid"><label class="wide">目标阶段<select v-model="form.stage" required><option value="">请选择阶段</option><option v-for="s in nextStages" :key="s" :value="s">{{stageNames[s]}}</option></select></label><label v-if="form.stage==='WON'" class="wide">实际成交金额（元）<input v-model="form.actualAmount" inputmode="decimal" required placeholder="最多两位小数"/></label><label class="wide">{{form.stage==='LOST'?'丢单原因':form.stage==='WON'?'成交说明':'阶段变更原因'}}<textarea v-model="form.reason" required maxlength="1000" rows="3"></textarea></label><label v-if="!['WON','LOST'].includes(form.stage)" class="wide">下一步<textarea v-model="form.nextAction" required maxlength="1000" rows="2"></textarea></label></div><p class="sales-muted">阶段逐步推进或回退。进入方案阶段需产品明细；进入签约准备和成交需该商机已批准且有效的报价。成交和丢单后只读。</p></template>
   <template v-else-if="dialog==='opportunity'"><div v-if="source" class="sales-callout">来自已转换线索：{{source.title}}。商机创建与线索转换为两次独立保存。</div><div class="sales-form-grid"><div class="sales-field wide"><strong>所属客户</strong><CustomerPicker v-model="form.customerId" :request="request" :selected-name="form.customerName" :disabled="busy||!canSave||!!editor||!!source"/></div><label class="wide">商机名称<input v-model="form.title" required maxlength="200"/></label><label>预计金额（元）<input v-model="form.amount" required inputmode="decimal" :readonly="!!opp?.hasLines"/><small v-if="opp?.hasLines">已由下方产品明细汇总，请在明细中调整</small></label><label>预计成交日期<input v-model="form.closeDate" type="date" required min="2000-01-01" max="2100-12-31"/></label><label class="wide">负责人<select v-model="form.ownerMemberId" required><option value="">选择负责人</option><option v-if="opp&&!owners.some(m=>m.id===opp?.ownerMemberId)" :value="opp.ownerMemberId">{{opp.ownerName}}</option><option v-for="m in owners" :key="m.id" :value="m.id">{{m.name}}</option></select></label><label class="wide">下一步<textarea v-model="form.nextAction" :required="!opp||!['WON','LOST'].includes(opp.stage)" maxlength="1000" rows="2"></textarea></label><label class="wide">商机备注<textarea v-model="form.description" maxlength="4000" rows="3"></textarea></label></div></template>
   <template v-else-if="dialog==='task'"><div class="sales-form-grid"><label class="wide">待办内容<input v-model="form.title" required maxlength="200"/></label><label>执行人<select v-model="form.assigneeMemberId" required><option value="">选择执行人</option><option v-if="task&&!owners.some(m=>m.id===task?.assigneeMemberId)" :value="task.assigneeMemberId">{{task.assigneeName}}</option><option v-for="m in owners" :key="m.id" :value="m.id">{{m.name}}</option></select></label><label>截止日期<input v-model="form.dueDate" type="date" required min="2000-01-01" max="2100-12-31"/></label><label>优先级<select v-model="form.priority"><option v-for="(name,value) in priorityNames" :key="value" :value="value">{{name}}</option></select></label><label class="wide">执行说明<textarea v-model="form.description" maxlength="4000" rows="3"></textarea></label></div><div v-if="!editor&&customerRead" class="sales-field"><strong>关联客户（可选）</strong><CustomerPicker :model-value="form.customerId" :required="false" :request="request" :selected-name="form.customerName" :disabled="busy||!canSave" @update:model-value="chooseCustomer"/><button v-if="form.customerId&&!customerId" class="text-button" type="button" @click="chooseCustomer('')">改为独立待办</button></div><p v-else-if="form.customerId" class="sales-callout">{{form.customerName}} {{form.opportunityTitle?' · '+form.opportunityTitle:''}}</p></template>
   <template v-else><p v-if="editor" class="sales-callout">{{form.customerName}} {{form.opportunityTitle?' · '+form.opportunityTitle:''}} · {{date((editor as Activity).occurredAt)}}</p><div v-else class="sales-field"><strong>所属客户</strong><CustomerPicker :model-value="form.customerId" :request="request" :selected-name="form.customerName" :disabled="busy||!canSave||!!form.opportunityId" @update:model-value="chooseCustomer"/></div><div class="sales-form-grid"><label>沟通方式<select v-model="form.activityType"><option v-for="(name,value) in activityNames" :key="value" :value="value">{{name}}</option></select></label><label v-if="!editor">沟通时间（上海）<input v-model="form.occurredAt" type="datetime-local" required/></label><label class="wide">沟通内容与结果<textarea v-model="form.content" required maxlength="4000" rows="5"></textarea></label></div><p class="sales-muted">跟进记录保存后保持原始内容，可新增记录补充；不会自动发送邮件或创建待办。</p></template>
   <div v-if="['task','activity'].includes(dialog)&&!editor&&form.customerId&&access.opportunities.read" class="sales-field"><strong>关联商机（可选）</strong><div class="sales-choice-search"><input v-model="opQuery" maxlength="100" placeholder="查找此客户的商机" aria-label="搜索关联商机" @keydown.enter.prevent="opPage=1;loadChoices()"/><button type="button" class="btn secondary" :disabled="opLoading||busy" @click="opPage=1;loadChoices()">查找</button></div><select v-model="form.opportunityId" :disabled="opLoading"><option value="">仅关联客户</option><option v-if="form.opportunityId&&!opChoices.some(o=>o.id===form.opportunityId)" :value="form.opportunityId">{{form.opportunityTitle||'当前关联商机'}}</option><option v-for="o in opChoices" :key="o.id" :value="o.id">{{o.title}} · {{stageNames[o.stage]}}</option></select><div class="sales-row sales-muted"><span>第 {{opPage}} 页 · {{opTotal}} 项</span><button type="button" :disabled="opLoading||opPage<=1" @click="choicePage(-1)">上一页</button><button type="button" :disabled="opLoading||opPage*20>=opTotal" @click="choicePage(1)">下一页</button></div></div>
  </fieldset>
  <template v-if="dialog==='opportunity'&&opp"><div class="sales-callout"><strong>{{stageNames[opp.stage]}}</strong> · 成交金额 {{money(opp.actualAmountCents)}}<p v-if="opp.sourceLeadName">来源线索：{{opp.sourceLeadName}}</p><div class="sales-actions"><button v-if="opp.canWrite&&!readonly" type="button" class="text-button" @click="openStage(opp)">推进阶段</button><button v-if="opp.canLink&&access.activityWrite&&customerWrite&&!readonly" type="button" class="text-button" @click="linkFromDetail('activity')">记录跟进</button><button v-if="opp.canLink&&access.tasks.write&&customerWrite&&!readonly" type="button" class="text-button" @click="linkFromDetail('task')">安排待办</button><button type="button" class="text-button" @click="showCustomer()">查看客户</button></div></div><OpportunityLines :opportunity="opp" :request="request" :can-write="!!opp.canWrite&&!opp.linesLocked&&!readonly" :product-read="productRead" @updated="linesUpdated"/><div class="sales-stage-tabs"><button type="button" :class="{active:detailTab==='history'}" :disabled="busy" @click="run(()=>detail('history'))">阶段历史</button><button v-if="access.activityRead" type="button" :class="{active:detailTab==='activities'}" :disabled="busy" @click="run(()=>detail('activities'))">关联跟进</button><button v-if="access.tasks.read" type="button" :class="{active:detailTab==='tasks'}" :disabled="busy" @click="run(()=>detail('tasks'))">关联待办</button></div><template v-if="detailTab==='history'"><article v-for="h in historyRows" :key="h.id" class="sales-history"><strong>{{h.fromStage?stageNames[h.fromStage]+' → ':''}}{{stageNames[h.toStage]}}</strong><small>{{h.actorName}} · {{date(h.createdAt)}} · 版本 {{h.businessVersion}}</small><p>{{h.reason}}</p><p v-if="h.nextAction">下一步：{{h.nextAction}}</p><p>预计 {{money(h.amountCents)}}<span v-if="h.actualAmountCents!=null"> · 成交 {{money(h.actualAmountCents)}}</span></p></article><div class="sales-row sales-muted"><span>历史 {{historyTotal}} 项 · 第 {{historyPage}} 页</span><button type="button" :disabled="busy||historyPage<=1" @click="historyTurn(-1)">上一页</button><button type="button" :disabled="busy||historyPage*20>=historyTotal" @click="historyTurn(1)">下一页</button></div></template><template v-else-if="detailTab==='activities'"><article v-for="a in linkedActivities" :key="a.id" class="sales-history"><strong>{{activityNames[a.activityType]}} · {{a.actorName}}</strong><small>{{date(a.occurredAt)}}</small><p>{{a.content}}</p></article><p class="sales-muted">显示最近 20 条。完整记录可在“客户跟进”按客户查看。</p></template><template v-else><article v-for="t in linkedTasks" :key="t.id" class="sales-history"><strong>{{t.title}}</strong><small>{{t.assigneeName}} · {{t.dueDate}} · {{t.status==='DONE'?'已完成':'未完成'}}</small></article><p class="sales-muted">显示前 20 项。全部待办可在“跟进待办”按客户查看。</p></template></template>
  <div v-if="error" class="sales-alert error" role="alert">{{error}}</div></div><footer class="sales-dialog-footer"><small>{{canSave?'保存时检查当前权限和记录版本':'当前资料只读'}}</small><button type="button" class="btn secondary" :disabled="busy" @click="close">{{canSave?'取消':'关闭'}}</button><button v-if="canSave" class="btn primary" :disabled="busy">{{busy?'正在保存…':dialog==='stage'?'确认阶段变更':'保存'}}</button></footer></form></section></div></Teleport>
 </section>
